"""Regenerate docs/samples.js from examples/*.json so the demo's sample
loader uses exactly the same files as the CLI.

    python3 tools/sync_samples.py          # rewrite docs/samples.js
    python3 tools/sync_samples.py --check  # exit 1 if it is out of date
"""

import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
EXAMPLES = ROOT / "examples"
TARGET = ROOT / "docs" / "samples.js"

HEADER = (
    "/* Generated by tools/sync_samples.py from examples/*.json. Do not edit by hand.\n"
    " * SYNTHETIC EXAMPLE — ILLUSTRATIVE FIGURES ONLY, NOT MARKET DATA.\n"
    " */\n"
)


def sample_files():
    return sorted(EXAMPLES.glob("*.json"))


def render():
    samples = [json.loads(p.read_text(encoding="utf-8")) for p in sample_files()]
    body = json.dumps(samples, indent=2, ensure_ascii=False)
    return HEADER + "window.STARTUP_SAMPLES = " + body + ";\n"


def main(argv):
    text = render()
    if "--check" in argv:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != text:
            print("docs/samples.js is out of date; run python3 tools/sync_samples.py")
            return 1
        print("docs/samples.js is up to date")
        return 0
    TARGET.write_text(text, encoding="utf-8")
    print(f"wrote {TARGET.relative_to(ROOT)} ({len(sample_files())} samples)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
